def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')

    if opp_def > n * 0.6:
        return 'D'

    probe_idx = -1
    for i in range(n):
        if me[i] == 'D':
            if all(opp[j] == 'C' for j in range(i)):
                probe_idx = i
                break

    if probe_idx != -1:
        if probe_idx + 1 < n:
            if opp[probe_idx + 1] == 'C':
                recent_opp_def = sum(1 for a in opp[-5:] if a == 'D')
                if recent_opp_def >= 2:
                    return 'C'
                return 'D'
            else:
                if opp_def > 2 or (n >= 5 and sum(1 for a in opp[-5:] if a == 'D') >= 2):
                    return 'D'
                return 'C'
        else:
            return 'C'
    else:
        if n >= 10 and opp_def == 0 and me_def == 0:
            return 'D'
        if opp[-1] == 'D':
            if opp_def <= max(1, n // 10):
                return 'C'
            return 'D'
        return 'C'
